import 'dart:convert';
import 'dart:typed_data';

class QrData {
  static const String purvaBase64 = '';

  static const String manasBase64 = '';

  static Uint8List? _cachedPurvaBytes;
  static Uint8List? _cachedManasBytes;

  static Uint8List get purvaBytes => _cachedPurvaBytes ??= base64Decode(purvaBase64);
  static Uint8List get manasBytes => _cachedManasBytes ??= base64Decode(manasBase64);
}
